def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    if b <= a:
        return 0

    fields = spec.split()
    if len(fields) != 3:
        raise ValueError("spec must have exactly 3 fields")

    minute_set = parse_field(fields[0], 59)
    hour_set = parse_field(fields[1], 23)
    weekday_set = parse_field(fields[2], 6)

    # Compute fires per week (1440 minutes = 7 days)
    fires_per_week = 0
    for t in range(1440):
        if t % 60 in minute_set and (t // 60) % 24 in hour_set and (t // 1440) % 7 in weekday_set:
            fires_per_week += 1

    # Compute total count
    weeks = (b - a) // 1440
    rem = (b - a) % 1440
    total = weeks * fires_per_week + count_fires_in_range(minute_set, hour_set, weekday_set, a % 1440, a % 1440 + rem)

    # Subtract blackouts coverage of [a, b)
    merged = merge_blackouts(blackouts)
    for s, e in merged:
        overlap = max(0, min(b, e) - max(a, s))
        total -= overlap

    return total


def parse_field(spec: str, max_val: int) -> set[int]:
    terms = spec.split(',')
    if not terms:
        raise ValueError("empty term")

    result = set()
    for term in terms:
        if term == '*':
            result = set(range(max_val + 1))
            break
        elif '/' in term:
            parts = term.split('/')
            if len(parts) != 2:
                raise ValueError("multiple '/'")
            base, step_str = parts[0], parts[1]
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError("step must be integer")
            if step < 1:
                raise ValueError("step must be >= 1")

            if base == '*':
                for v in range(0, max_val + 1, step):
                    result.add(v)
            elif '-' in base:
                parts2 = base.split('-')
                if len(parts2) != 2:
                    raise ValueError("invalid range")
                n_str, m_str = parts2[0], parts[1]
                try:
                    n = int(n_str)
                    m = int(m_str)
                except ValueError:
                    raise ValueError("invalid range values")
                if n > m:
                    raise ValueError("N > M")
                if n < 0 or m > max_val:
                    raise ValueError("value out of range")
                for v in range(n, m + 1, step):
                    result.add(v)
            else:
                try:
                    n = int(base)
                except ValueError:
                    raise ValueError("invalid number")
                if n < 0 or n > max_val:
                    raise ValueError("value out of range")
                for v in range(n, max_val + 1, step):
                    result.add(v)
        else:
            if '-' in term:
                parts = term.split('-')
                if len(parts) != 2:
                    raise ValueError("invalid range")
                n_str, m_str = parts[0], parts[1]
                try:
                    n = int(n_str)
                    m = int(m_str)
                except ValueError:
                    raise ValueError("invalid range values")
                if n > m:
                    raise ValueError("N > M")
                if n < 0 or m > max_val:
                    raise ValueError("value out of range")
                for v in range(n, m + 1):
                    result.add(v)
            else:
                try:
                    n = int(term)
                except ValueError:
                    raise ValueError("invalid number")
                if n < 0 or n > max_val:
                    raise ValueError("value out of range")
                result.add(n)

    return result


def count_fires_in_range(minute_set, hour_set, weekday_set, start: int, end: int) -> int:
    count = 0
    for t in range(start, end):
        if t % 60 in minute_set and (t // 60) % 24 in hour_set and (t // 1440) % 7 in weekday_set:
            count += 1
    return count


def merge_blackouts(blackouts: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not blackouts:
        return []
    sorted_blackouts = sorted(blackouts, key=lambda x: x[0])
    merged = []
    for s, e in sorted_blackouts:
        if merged and merged[-1][1] > s:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    return merged
