class FairQueue:
    """A job queue with priorities that grow while a job waits ("aging")."""

    def __init__(self, aging: int, cap: int):
        if aging < 1 or cap < 0:
            raise ValueError("aging >= 1 and cap >= 0")
        self.aging = aging
        self.cap = cap
        # name -> {'state', 'base', 'waiting_time', 'enqueue_order'}
        self._jobs: dict[str, dict] = {}

    def _effective_priority(self, job_info, t):
        """Compute effective priority at time t."""
        return job_info['base'] + min(self.cap, job_info['waiting_time'] // self.aging)

    def submit(self, job, priority, t):
        """Add a new WAITING job. Raise ValueError if job already exists."""
        if job in self._jobs and self._jobs[job]['state'] in ('WAITING', 'PAUSED', 'RUNNING'):
            raise ValueError("job already in queue")
        self._jobs[job] = {
            'state': 'WAITING',
            'base': priority,
            'waiting_time': 0,
            'enqueue_order': len(self._jobs),
        }

    def start(self, t):
        """Start the highest-ranked WAITING job. Return its name or None."""
        if not self._jobs:
            return None
        waiting = [(name, info) for name, info in self._jobs.items()
                   if info['state'] == 'WAITING']
        # Higher effective priority first; then larger waiting time; then earlier enqueue.
        waiting.sort(key=lambda x: (
            -self._effective_priority(x[1], t),
            -x[1]['waiting_time'],
            x[1]['enqueue_order'],
        ))
        name, info = waiting[0]
        info['state'] = 'RUNNING'
        return name

    def finish(self, job, t):
        """A RUNNING job is done and gone. KeyError if not RUNNING."""
        info = self._jobs.get(job)
        if info is None or info['state'] != 'RUNNING':
            raise KeyError(job)
        del self._jobs[job]

    def requeue(self, job, t):
        """A RUNNING job goes back to WAITING. Base priority drops by 1."""
        info = self._jobs.get(job)
        if info is None or info['state'] != 'RUNNING':
            raise KeyError(job)
        info['base'] -= 1
        info['state'] = 'WAITING'
        info['enqueue_order'] = len(self._jobs)

    def pause(self, job, t):
        """A WAITING job becomes PAUSED. Returns True; False if already PAUSED."""
        info = self._jobs.get(job)
        if info is None:
            raise KeyError(job)
        if info['state'] == 'PAUSED':
            return False
        if info['state'] != 'WAITING':
            raise KeyError(job)
        info['state'] = 'PAUSED'
        return True

    def resume(self, job, t):
        """A PAUSED job becomes WAITING again. Returns True; False if already WAITING."""
        info = self._jobs.get(job)
        if info is None:
            raise KeyError(job)
        if info['state'] == 'WAITING':
            return False
        if info['state'] != 'PAUSED':
            raise KeyError(job)
        info['state'] = 'WAITING'
        return True

    def cancel(self, job):
        """Remove the job whatever its state. Returns True if removed."""
        return self._jobs.pop(job, None) is not None

    def queue(self, t):
        """Return WAITING jobs as [(name, effective priority at t), ...] in start order."""
        waiting = [(name, info) for name, info in self._jobs.items()
                   if info['state'] == 'WAITING']
        waiting.sort(key=lambda x: (
            -self._effective_priority(x[1], t),
            -x[1]['waiting_time'],
            x[1]['enqueue_order'],
        ))
        return [(name, self._effective_priority(info, t)) for name, info in waiting]


class KeyError(Exception):
