        elif seg.startswith(':?'):
            name = seg[1:]
            remaining_pattern_min = count_nonflexible(pattern_segments[j+1:])
            if len(path_segments) - i >= remaining_pattern_min:
                result[name] = None
                j += 1  # Don't increment i (matched 0 segments)
            else:
                # Need to match 1 segment
                if path_segments[i] != '':
                    result[name] = path_segments[i]
                    i += 1
                    j += 1
                else:
                    return None
        elif seg.startswith('#'):
            name = seg[1:]
            if path_segments[i].isdigit():
                result[name] = int(path_segments[i])
                i += 1
                j += 1
            else:
                return None
        elif seg.startswith('*'):
            name = seg[1:]
            remaining_pattern_min = count_nonflexible(pattern_segments[j+1:])

            # Try k from 0 up, pruning when len(path_segments) - i - k < remaining_pattern_min.
            for k in range(len(path_segments) - i):
                if len(path_segments) - i - k < remaining_pattern_min:
                    break  # Pruning: can't match even with this k

                # Check if after consuming k segments, the remaining pattern can match the remaining path exactly.
                if _match_remaining(pattern_segments[j+1:], path_segments[i+k:]):
                    result[name] = path_segments[i:i+k]
                    i += k
                    j += 1
                    break  # Found minimum k
            else:
                return None  # No k works

        else:
            # Literal segment
            if path_segments[i] == seg:
                i += 1
                j += 1
            else:
                return None

    if j < len(pattern_segments):
        return None  # More pattern segments than path can account for

    return result

def count_nonflexible(segments):
    """Count the minimum number of path segments needed to match a list of pattern segments."""
    count = 0
    for seg in segments:
        if seg.startswith(':') or seg.startswith('#'):
            count += 1  # These need exactly 1 segment
        elif seg.startswith('*'):
            pass  # *name can match 0 segments (minimum is 0)
        elif seg.startswith(':?'):
            pass  # :name? can match 0 segments (minimum is 0)
        else:
            count += 1  # Literal needs 1 segment
    return count

def _match_remaining(pattern_segments, path_segments):
    """Recursively check if the remaining pattern can match the remaining path exactly."""
    if len(path_segments) == 0:
        # Check if there are only flexible segments in the remaining pattern (which can match 0).
        return all(seg.startswith('*') or seg.startswith(':?') for seg in pattern_segments)

    if len(pattern_segments) == 0:
        # No pattern segments left. Can't match any remaining path segments.
        return False

    seg = pattern_segments[0]

    if seg.startswith(':'):
        name = seg[1:]
        return len(path_segments) > 0 and path_segments[0] != '' and _match_remaining(pattern_segments[1:], path_segments[1:])

    elif seg.startswith(':?'):
        name = seg[1:]
        # Try to match 0 segments (None) first. If the remaining pattern can match the remaining path, use None.
        if _match_remaining(pattern_segments[1:], path_segments):
            return True
        else:
            # Need to match 1 segment.
            return len(path_segments) > 0 and path_segments[0] != '' and _match_remaining(pattern_segments[1:], path_segments[1:])

    elif seg.startswith('#'):
        name = seg[1:]
        return len(path_segments) > 0 and all(c.isdigit() for c in path_segments[0]) and _match_remaining(pattern_segments[1:], path_segments[1:])

    elif seg.startswith('*'):
        name = seg[1:]
        remaining_pattern_min = count_nonflexible(pattern_segments[1:])
        if len(path_segments) < remaining_pattern_min:
            return False

        for k in range(len(path_segments)):
            if len(path_segments) - k < remaining_pattern_min:
                break  # Pruning

            if _match_remaining(pattern_segments[1:], path_segments[k:]):
                return True

        return False

    else:
        # Literal
        return len(path_segments) > 0 and path_segments[0] == seg and _match_remaining(pattern_segments[1:], path_segments[1:])
