import re


def run_script(source: str, max_steps: int) -> tuple[list[int], str]:
    """Interpret the Ember language and return (emitted_values, status)."""
    lines = source.split("\n")

    # Tokenize lines, ignoring empty lines and comment lines
    parsed_lines = []
    for line in lines:
        tokens = line.split()
        if not tokens or tokens[0].startswith("#"):
            continue
        parsed_lines.append(tokens)

    # Static checking
    try:
        _static_check(parsed_lines)
    except ValueError:
        raise

    # Execute
    variables = {}
    emitted = []
    steps = 0
    status = "done"

    def evaluate(expr_tokens):
        """Evaluate an expression token list left to right."""
        if len(expr_tokens) == 0:
            raise ValueError("empty expression")

        # Validate alternation: operand, operator, operand, ...
        for i in range(0, len(expr_tokens)):
            if i == 0:
                if not _is_operand(expr_tokens[0]):
                    raise ValueError("bad operand at start")
                continue
            if (i % 2) == 0:
                if not _is_operand(expr_tokens[i]):
                    raise ValueError("bad operand")
                continue
            else:
                if expr_tokens[i] not in ("+", "-", "*", "/", "%", "<", ">", "="):
                    raise ValueError("bad operator")
        # Last token must be an operand
        if len(expr_tokens) % 2 != 0:
            raise ValueError("bad alternation: ends with operator")

        # Evaluate left to right
        result = _parse_operand(expr_tokens[0])
        for i in range(1, len(expr_tokens), 2):
            op = expr_tokens[i]
            operand = _parse_operand(expr_tokens[i + 1])
            if op == "+":
                result = result + operand
            elif op == "-":
                result = result - operand
            elif op == "*":
                result = result * operand
            elif op == "/":
                if operand == 0:
                    raise ValueError("division by zero")
                result = result // operand
            elif op == "%":
                if operand == 0:
                    raise ValueError("modulo by zero")
                result = result % operand
            elif op == "<":
                result = 1 if result < operand else 0
            elif op == ">":
                result = 1 if result > operand else 0
            elif op == "=":
                result = 1 if result == operand else 0
        return result

    def _parse_operand(token):
        """Parse an operand (integer literal or variable)."""
        # Integer literal with optional leading minus
        match = re.match(r"-?\d+", token)
        if match:
            return int(match.group())

        # Variable name: lowercase letters a-z only
        if re.match(r"[a-z][a-z]*", token):
            return variables.get(token, 0)

        raise ValueError("bad operand")

    def _is_operand(token):
        """Check if token is a valid operand."""
        return re.match(r"-?\d+", token) or re.match(r"[a-z][a-z]*", token)

    def _is_operator(token):
        """Check if token is a valid operator."""
        return token in ("+", "-", "*", "/", "%", "<", ">", "=")

    # Track blocks for static and execution checking
    block_stack = []  # list of (type, has_else) where type is 'if' or 'while'

    def _check_break_or_skip():
        """Check if we're inside a while loop."""
        return any(b[0] == "while" for b in block_stack)

    def _process_line(tokens):
        nonlocal steps, status, variables, emitted

        op = tokens[0]

        if op == "set":
            if len(tokens) != 3:
