            expr_str = tokens[1]
            # Validate expression
            _validate_expr(expr_str.split())
            steps += 1
            block_stack.append(("if", False))

            # Check condition
            cond_val = evaluate(tokens[1].split())
            if cond_val != 0:
                # Execute then branch
                while True:
                    next_tokens = _next_line_for_if()
                    if not next_tokens or next_tokens[0] == "end":
                        break
                    if next_tokens[0] == "else":
                        block_stack[-1][1] = True
                        # Skip to else branch, but execute it
