            steps += 1
            block_stack.append(("while", None))  # No else for while

            cond_val = evaluate(tokens[1].split())
            while cond_val != 0:
                while True:
                    next_tokens = _next_line_for_while()
                    if not next_tokens or next_tokens[0] == "end":
