import collections
from collections import defaultdict

class VaultKV:
    def __init__(self):
        self._data = {}  # key -> value
        self._locks = {}  # key -> bool (locked or not)
        self._reverse_index = defaultdict(set)  # value -> set of keys
        self._tx_stack = []  # stack of transaction frames
        self._tx_depth = 0

    def put(self, key, value):
        # Check lock first
        if self.locked(key):
            raise PermissionError(f"Key '{key}' is locked")
