def craft_cost(prices: dict[str, int], recipes: list[tuple[str, int, dict[str, int]]], target: str) -> int | None:
    import math

    # Build adjacency: product -> [(fee, ingredients_dict)]
    prod_recipes = {}
    for (product, fee, ingredients) in recipes:
        if product not in prod_recipes:
            prod_recipes[product] = []
        prod_recipes[product].append((fee, ingredients))

    # Build reverse adjacency: ingredient -> [(product, fee)]
    ing_adj = {}
    for (product, fee, ingredients) in recipes:
        for item, qty in ingredients.items():
        if item not in ing_adj:
            ing_adj[item] = []
        ing_adj[item].append((product, fee, qty))

    # Initialize costs: price or infinity
    cost = {}
    for name in prices:
        cost[name] = prices[name]
    for prod in prod_recipes:
        if prod not in cost:
            cost[prod] = math.inf

    # Bellman-Ford relaxation: N iterations where N = len(recipes)
    # Each iteration relaxes all recipes; if no improvement occurs, we're done
    n = len(recipes)
    for _ in range(n):
        changed = False
        for prod, list_of_recipes in prod_recipes.items():
            best = cost[prod]  # current cheapest way to get this product
            for fee, ingredients in list_of_recipes:
                # Check if all ingredients are obtainable (finite cost)
                all_obt = True
                total_ingredient_cost = 0
                for item, qty in ingredients.items():
                    if item not in cost or cost[item] == math.inf:
                        all_obt = False
                        break
                    total_ingredient_cost += cost[item] * qty
                if all_obt:
                    new_cost = fee + total_ingredient_cost
                    if new_cost < best:
                        cost[prod] = new_cost
                        changed = True
        if not changed:
            break

    # After n iterations, any item whose cost still decreased is in a cycle
    # For such items, their recipe-based cost is effectively infinite (they can't be made from each other for less)
    # They might still be obtainable via buying if they have a price
    final_cost = {}
    for name in cost:
        if cost[name] == math.inf and name not in prices:
            final_cost[name] = math.inf  # unobtainable
        else:
            final_cost[name] = cost[name]

    # Compute the actual cost of target using memoization (to handle any remaining cycles cleanly)
    memo = {}

    def get_cost(item):
        if item in memo:
            return memo[item]
        if item == target:
            pass  # We're computing the cost for the target; no circularity check needed here since we already did relaxation

        if item in final_cost:
            return final_cost[item]

        # Not obtainable via buying or relaxed recipes
        # Check if it's part of a cycle (cost was infinite but price exists) - handled by final_cost

        return math.inf

    # For the target, compute using memoization to avoid infinite recursion in cycles
    # Note: We already did relaxation so all finite costs are known; for items with infinite cost
    # from relaxation (but a price), we use the price. For truly unobtainable items, it's inf.

    def compute_cost(item):
        if item in memo:
            return memo[item]

        # First check if this is the target - if so, we need to be careful with cycles
        # Actually, since we already relaxed, the cost should be known unless it's in a cycle

        # If item has a price, that's an upper bound
        if item in prices:
            return min(prices[item], compute_cost_via_recipes(item))

        # Otherwise try recipes
        if item not in prod_recipes or not prod_recipes[item]:
            return math.inf

        # For each recipe, compute cost = fee + sum(qty * cost(ingredient))
        best = math.inf
        for fee, ingredients in prod_recipes[item]:
            total = fee
            for ing, qty in ingredients.items():
                if compute_cost(ing) == math.inf:  # Ingredient unobtainable
                    total = math.inf
                    break
                total += compute_cost(ing) * qty
            if total < best:
                best = total

        return best

    def compute_cost_via_recipes(item):
        """Only tries recipes (ignores buying price). Used to check if recipe-based cost is better than buy."""
        if item not in prod_recipes or not prod_recipes[item]:
            return math.inf

        best = math.inf
        for fee, ingredients in prod_recipes[item]:
            total = fee
            for ing, qty in ingredients.items():
                if compute_cost(ing) == math.inf:
                    total = math.inf
                    break
                total += compute_cost(ing) * qty
            if total < best:
                best = total

        return best

    result = compute_cost(target)

    # If target is not in prices and no reachable recipe (all ingredients unobtainable), it's None
    if result == math.inf:
        return None

    return result
